+import { expect, test } from "bun:test";
+import { distinctInWindow, type Event } from "./window";
+
+// The original O(n^2) implementation, kept as the behaviour reference.
+function reference(events: Event[], windowMs: number): number[] {
+  return events.map((e) => {
+    const keys = new Set<string>();
+    for (const other of events) if (other.t > e.t - windowMs && other.t <= e.t) keys.add(other.key);
+    return keys.size;
+  });
+}
+
+test("the window is (t - windowMs, t]: the start is excluded, the end included", () => {
+  expect(distinctInWindow([{ t: 0, key: "a" }, { t: 10, key: "b" }], 10)).toEqual([1, 1]);
+  expect(distinctInWindow([{ t: 1, key: "a" }, { t: 10, key: "b" }], 10)).toEqual([1, 2]);
+});
+
+test("all events count, whatever their order, including later entries with an earlier or equal time", () => {
+  const events = [
+    { t: 8, key: "a" },
+    { t: 0, key: "b" },
+    { t: 8, key: "c" },
+    { t: 5, key: "a" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([3, 2, 3, 2]);
+});
+
+test("duplicate keys in a window count once", () => {
+  expect(distinctInWindow([{ t: 1, key: "a" }, { t: 2, key: "a" }, { t: 3, key: "a" }], 10)).toEqual([1, 1, 1]);
+});
+
+test("keys are compared exactly as strings", () => {
+  expect(distinctInWindow([{ t: 1, key: "a" }, { t: 1, key: "A" }], 10)).toEqual([2, 2]);
+  expect(distinctInWindow([{ t: 1, key: "1" }, { t: 1, key: " 1" }], 10)).toEqual([2, 2]);
+});
+
+test("a windowMs that is not finite and above 0 is a RangeError naming windowMs", () => {
+  for (const w of [0, -1, NaN, Infinity, -Infinity]) {
+    expect(() => distinctInWindow([{ t: 1, key: "a" }], w)).toThrow(RangeError);
+    expect(() => distinctInWindow([{ t: 1, key: "a" }], w)).toThrow(/windowMs/);
+  }
+});
+
+test("a bad windowMs is reported before a bad time", () => {
+  expect(() => distinctInWindow([{ t: NaN, key: "a" }], 0)).toThrow(RangeError);
+});
+
+test("a non-finite or non-number time is a TypeError naming the first bad index", () => {
+  const ok = { t: 1, key: "a" };
+  expect(() => distinctInWindow([ok, { t: NaN, key: "b" }, { t: "3", key: "c" } as unknown as Event], 10)).toThrow(
+    new TypeError("event 1 has no finite time: NaN"),
+  );
+  expect(() => distinctInWindow([ok, { t: Infinity, key: "b" }], 10)).toThrow(TypeError);
+  expect(() => distinctInWindow([ok, { key: "b" } as unknown as Event], 10)).toThrow(/event 1/);
+  expect(() => distinctInWindow([{ t: "3", key: "c" } as unknown as Event], 10)).toThrow(/event 0/);
+});
+
+test("when t - windowMs equals t, even the event itself is out of its window", () => {
+  expect(distinctInWindow([{ t: 1e300, key: "a" }], 1)).toEqual([0]);
+  expect(distinctInWindow([{ t: 0, key: "a" }, { t: -0, key: "b" }], 10)).toEqual([2, 2]);
+});
+
+test("matches the reference on seeded random inputs", () => {
+  let s = 12345;
+  const next = () => {
+    s = (s * 1664525 + 1013904223) % 4294967296;
+    return s / 4294967296;
+  };
+  const windows = [0.5, 1, 3, 10, 1e9];
+  for (let c = 0; c < 300; c++) {
+    const n = Math.floor(next() * 61);
