diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/recovery.test.ts b/test/recovery.test.ts
--- a/test/recovery.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/recovery.test.ts	2026-10-30 02:23:05.613243046 +0000
@@ -0,0 +1,93 @@
+import { describe, expect, test } from 'bun:test';
+import { mkdtempSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { loadQuotaWait } from '../src/core/config.ts';
+import { runPrompt, type RunOptions } from '../src/core/loop/run.ts';
+import { FAUX_MODEL } from '../src/core/providers/catalog.ts';
+import { fauxProvider, text, toolUse, type FauxStep } from '../src/core/providers/faux.ts';
+import { lintSession } from '../src/core/session/lint.ts';
+import { SessionLog } from '../src/core/session/log.ts';
+import { bashTool } from '../src/core/tools/bash.ts';
+import { readTool } from '../src/core/tools/read.ts';
+import type { EventOf, SessionEvent } from '../src/core/types.ts';
+
+const cwd = mkdtempSync(join(tmpdir(), 'cedia-recovery-'));
+writeFileSync(join(cwd, 'a.txt'), 'alpha\n');
+const MIN = 60_000;
+
+function setup(steps: FauxStep[], extra: Partial<RunOptions> = {}) {
+  const log = SessionLog.create();
+  const opts: RunOptions = {
+    log,
+    provider: fauxProvider(steps),
+    model: FAUX_MODEL,
+    tools: [readTool, bashTool],
+    system: 'sys',
+    cwd,
+    retry: { sleep: async () => {} },
+    ...extra,
+  };
+  return { log, opts };
+}
+
+const of = <K extends SessionEvent['kind']>(events: SessionEvent[], k: K) => events.filter((e): e is EventOf<K> => e.kind === k);
+const spent = (retryAfterMs: number): FauxStep => ({ error: { code: 'quota', status: 429, retryAfterMs, message: 'usage limit reached' } });
+
+describe('recovery', () => {
+  test('abort during a quota wait ends at once with interrupted', async () => {
+    const ac = new AbortController();
+    const { opts } = setup([spent(10 * MIN), { blocks: [text('unreachable')] }], { signal: ac.signal, retry: {}, quotaWaitMs: 30 * MIN });
+    const p = runPrompt(opts, 'wait');
+    setTimeout(() => ac.abort(), 10);
+    const start = Date.now();
+    expect((await p).subtype).toBe('interrupted');
+    expect(Date.now() - start).toBeLessThan(1000);
+  });
+
+  test('quota waits do not count against retry.max', async () => {
+    const { opts } = setup([spent(MIN), spent(MIN), { blocks: [text('ok')] }], { quotaWaitMs: 30 * MIN, retry: { max: 2, sleep: async () => {} } });
+    expect(await runPrompt(opts, 'hi')).toMatchObject({ subtype: 'success', result: 'ok' });
+  });
+
+  test('two calls that share an id on the over-budget path give one not_started result', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('dup', 'read', { path: 'a.txt' }), toolUse('dup', 'read', { path: 'a.txt' })] }], { maxBudgetUsd: 0 });
+    expect((await runPrompt(opts, 'go')).subtype).toBe('error_max_budget_usd');
+    const results = of(log.events, 'tool_result');
+    expect(results.map((r) => [r.callId, r.status])).toEqual([['dup', 'not_started']]);
+    expect(lintSession(log.events)).toEqual([]);
+  });
+
+  test('a refusal with a tool call in the same reply keeps the log paired', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('c1', 'read', { path: 'a.txt' }), text('no')], stop: 'refusal' }]);
+    expect(await runPrompt(opts, 'go')).toMatchObject({ subtype: 'error_during_execution', result: 'no' });
+    expect(of(log.events, 'tool_result').map((r) => [r.callId, r.status])).toEqual([['c1', 'not_started']]);
+    expect(lintSession(log.events)).toEqual([]);
+  });
+
+  test('on-quota wait:<minutes> is 1 to 50 whole minutes, and anything else is refused', () => {
+    for (let n = 1; n <= 50; n++) expect(loadQuotaWait(`wait:${n}`)).toBe(n * MIN);
+    for (const bad of ['wait', 'wait:0', 'wait:-1', 'wait:1.5', 'later', 'Wait:5'])
+      expect(() => loadQuotaWait(bad)).toThrow('fallback or wait:<minutes>');
+  });
+
+  test('a quota error that says to retry now is not waited out, so the run cannot loop', async () => {
+    const { log, opts } = setup([spent(0), spent(0), spent(0), { blocks: [text('unreachable')] }], { quotaWaitMs: 30 * MIN });
+    expect((await runPrompt(opts, 'hi')).subtype).toBe('error_during_execution');
+    expect(of(log.events, 'attempt')).toHaveLength(1);
+  });
+
+  test('quota waits add up over the run, and the wait that would pass the ceiling ends it', async () => {
+    const waits: number[] = [];
+    const { log, opts } = setup([spent(10 * MIN), spent(10 * MIN), spent(10 * MIN), spent(10 * MIN), { blocks: [text('unreachable')] }], { quotaWaitMs: 30 * MIN, onQuotaWait: (ms) => void waits.push(ms) });
+    expect((await runPrompt(opts, 'hi')).subtype).toBe('error_during_execution');
+    expect(waits).toEqual([10 * MIN, 10 * MIN, 10 * MIN]);
+    expect(of(log.events, 'attempt')).toHaveLength(4);
+  });
+
+  test('an unknown tool name is cut to 64 characters in its result', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('c1', 'y'.repeat(300), {})] }, { blocks: [text('ok')] }]);
+    expect((await runPrompt(opts, 'go')).subtype).toBe('success');
+    expect(of(log.events, 'tool_result')[0]!.output.text).toBe(`not run: unknown tool "${'y'.repeat(64)}"`);
+  });
+});

